create table if not exists customers (id uuid primary key default gen_random_uuid(), name text, phone text, email text, preferred_language text, created_at timestamptz default now());
create table if not exists providers (id uuid primary key default gen_random_uuid(), name text not null, category text not null, phone text, location text, verification_status text default 'unverified', active boolean default true, notes text, created_at timestamptz default now());
create table if not exists services (id uuid primary key default gen_random_uuid(), provider_id uuid references providers(id) on delete cascade, name text not null, category text not null, description text, price_min numeric, price_max numeric, currency text default 'ZMW', active boolean default true);
create table if not exists requests (id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id), raw_message text not null, intent text, requirements jsonb default '{}'::jsonb, status text default 'new', priority int default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists matches (id uuid primary key default gen_random_uuid(), request_id uuid references requests(id) on delete cascade, provider_id uuid references providers(id), service_id uuid references services(id), score numeric, reason jsonb default '{}'::jsonb, created_at timestamptz default now());
create table if not exists bookings (id uuid primary key default gen_random_uuid(), request_id uuid references requests(id), provider_id uuid references providers(id), service_id uuid references services(id), status text default 'pending', scheduled_for timestamptz, confirmed_at timestamptz, completed_at timestamptz);
create table if not exists interactions (id uuid primary key default gen_random_uuid(), request_id uuid references requests(id) on delete cascade, channel text, direction text, message text, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());
create table if not exists audit_events (id uuid primary key default gen_random_uuid(), request_id uuid references requests(id) on delete cascade, event_type text not null, actor_type text not null, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());
create index if not exists providers_category_idx on providers(category);
create index if not exists requests_status_idx on requests(status);
create index if not exists matches_request_idx on matches(request_id);
